-- The society must already exist, and exactly once. These were imported with
-- their flat counts and portal accounts, so a missing one is a mistake to
-- stop on rather than paper over by inserting a second row — and a DUPLICATE
-- one is worse, because every statement below matches by name and would
-- quietly write to both.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM societies WHERE name = 'RG Residency';
  IF n = 0 THEN RAISE EXCEPTION 'no society named %', 'RG Residency'; END IF;
  IF n > 1 THEN RAISE EXCEPTION '% societies named % — resolve the duplicate first', n, 'RG Residency'; END IF;
END $$;

UPDATE societies SET status = 'active' WHERE name = 'RG Residency';   -- address left as stored

INSERT INTO engagements (id, society_id, service_line, status, created_at)
SELECT 'bf-rg-residency-eng', s.id, 'lighting', 'active', now() FROM societies s WHERE s.name = 'RG Residency' ON CONFLICT DO NOTHING;

INSERT INTO pipelines (id, society_id, service_line, stage, contact_name, contact_phone,
                       meeting_date, sales_owner_id, logged_by_id, authoritative, notes,
                       created_at, updated_at)
SELECT 'bf-rg-residency-pipe', s.id, 'lighting', 'active_billing',
       'RG Residency', NULL, '2025-11-08'::date,
       a.id, a.id, true,
       'Backfilled from the signed agreement, the post-installation savings report and the first invoice. This deal predates the system: the date above is the agreement signature, not a meeting.',
       now(), now()
FROM societies s, admin_users a WHERE s.name = 'RG Residency' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO site_surveys (id, pipeline_id, created_at) VALUES ('bf-rg-residency-survey', 'bf-rg-residency-pipe', now()) ON CONFLICT DO NOTHING;

