-- The demo report. Not needed for billing, but without it the deal map sits
-- at "Demo savings report · In progress" while every later step reads done.
INSERT INTO demo_reports (id, pipeline_id, version, status,
                          pre_install_baseline_total, post_install_average_total, measured_savings_pct,
                          society_light_count, metered_light_count, extrapolation_factor,
                          projected_savings_kwh_per_day, circuit_snapshot, generated_at, shared_at, shared_by_id)
SELECT 'bf-rg-residency-demo-report', 'bf-rg-residency-pipe', 1, 'shared',
       c.pre_install_baseline, c.pre_install_baseline * (1 - c.benchmark_savings_pct / 100),
       c.benchmark_savings_pct, c.represented_light_count, c.metered_light_count,
       c.represented_light_count::double precision / c.metered_light_count,
       (c.pre_install_baseline * c.benchmark_savings_pct / 100)
         * (c.represented_light_count::double precision / c.metered_light_count),
       '[{"circuitId": "bf-rg-residency-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 69, "representedLightCount": 1444, "extrapolationFactor": 20.927536, "preInstallBaseline": 32.69, "postInstallAverage": 12.62, "savedKwhPerDay": 20.07, "benchmarkSavingsPct": 66.0, "projectedSavedKwhPerDay": 451.52, "preInstallReadings": [], "postInstallReadings": []}]'::jsonb, now(), '2025-11-08'::date, a.id
FROM circuits c, admin_users a
-- shared_by_id is an ADMIN, not a profile: FirsThing shares the report WITH
-- the society, so the sharer is internal. The mirror of offers, where
-- responded_by_id IS a profile because accepting is the society's act.
WHERE c.id = 'bf-rg-residency-ckt-1' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO offers (id, pipeline_id, version, status, benchmark_source, circuit_terms,
                    tolerance_pct, revenue_share_pct, unit_electricity_rate, term_months,
                    projected_monthly_fee, issued_at, issued_by_id, responded_at, responded_by_id, created_at)
SELECT 'bf-rg-residency-offer', 'bf-rg-residency-pipe', 1, 'accepted', 'negotiated_fixed', '[{"circuitId": "bf-rg-residency-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 69, "representedLightCount": 1444, "benchmarkSavingsPct": 66.0, "preInstallBaseline": 32.69, "projectedSavedKwhPerDay": 21.5754}]'::jsonb,
       5, 55.2044, 8.6267, 36,
       53034.00, '2025-11-08'::date, a.id,
       '2025-11-08'::date, p.id, now()
FROM admin_users a
LEFT JOIN societies soc ON soc.name = 'RG Residency'
LEFT JOIN profiles p ON p.society_id = soc.id AND p.portal_authority = 'office_bearer' AND p.is_active
WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO agreements (id, pipeline_id, offer_id, prepared_at, prepared_by_id,
                        printed_at, notarized_at, signed_at, deviation_note,
                        executed_s3_key, executed_file_name, uploaded_at, uploaded_by_id)
SELECT 'bf-rg-residency-agreement', 'bf-rg-residency-pipe', 'bf-rg-residency-offer', '2025-11-08'::date, a.id,
       -- Printed and notarised are the same day, and it is the e-stamp
       -- certificate date on page 1 (the user, 2026-08-27). It can fall after
       -- the front-page date, which is a backdated effective date rather than
       -- a mistake.
       '2025-11-08'::date, '2025-11-08'::date,
       '2025-11-08'::date,
       -- How this deal's figures were arrived at, in the field named for it.
       -- These societies predate the system and share no single method, so
       -- the basis travels with the agreement rather than living in a CSV.
       'Commissioned before this system existed. There was no single method across these societies, so how this deal''s figures were arrived at is recorded here rather than assumed. Departures from the standard: extrapolation-theoretical, fee-device-charge-plus-share-of-net, agreement-figures-do-not-reconcile, report-share-differs-from-agreement. SOURCE IS THE USER''S PASTED TEXT for the agreement and both demo reports; the invoices are real files. THE AGREEMENT''S BENCHMARK GOVERNS, on the user''s instruction (2026-08-28): ''the reports will have inconsistencies with whats in the agreement. so we will consider whatever is given in agreement as bench mark''. Its annexure gives no percentage outright, but its own figures do: 13,020.48 kWh saved of 19,728 = exactly 66.00%, and 19,728 is 1,370 x 20W x 24h x 30, the theoretical. THE AGREEMENT''S COMMERCIAL FIGURES DO NOT REPRODUCE THE INVOICE. Its annexure gives Rs 32,812 devices + Rs 15,902 (20% of the Rs 79,512 net) = Rs 48,714 for 1,370 lights, plus Rs 35 per light beyond that, which for the 1,444 installed would be Rs 51,304. The January 2026 invoice, a full 31 days, bills 1,444 x Rs 20 = Rs 28,880 of devices plus Rs 24,154 of servicing = Rs 53,034. The invoice is what the society pays, so Rs 53,034 is recorded and the share is derived from it: 44.7956% to FirsThing, 55.2044% to the society. Its implied rate is Rs 8.6267/kWh (112,324/13,020.48), higher than any other society here. Billing from 16 Dec 2025 - the first invoice covers 16 days of December - so installation finished on or before 15 Dec. That first invoice also carries a one-off Rs 2,800 Wifi Smart Meter, which is hardware and not part of the monthly charge. Notarised and signed 08 Nov 2025, though the agreement''s own opening line dates it the 6th. Tolerance +/-5%, from the termination clause: savings may vary +/-5%, below which termination is triggered. Both reports'' ''50% of these verified savings'' matches neither the agreement nor the invoice.',
       'Documents/RG_Residency/2025-11/Agreements/RG_Residency_Agreement_2025-11-08.pdf',
       'RG_Residency_Agreement_2025-11-08.pdf',
       -- The scan reaches us the day after signing.
       ('2025-11-08'::date + 1), a.id
FROM admin_users a WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO contracts (id, pipeline_id, society_id, service_line, agreement_id, status,
