       '[{"circuitId": "bf-rg-residency-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 69, "representedLightCount": 1444, "benchmarkSavingsPct": 66.0, "preInstallBaseline": 32.69, "projectedSavedKwhPerDay": 21.5754}]'::jsonb, a.id, now()
